/** Each language's values, in I18n.SUPPORTED order. */
internal fun i18nValuesOf(lang: String): Array<String?> = when (lang) {
    "nl" -> I18nNl.VALUES
    "fr" -> I18nFr.VALUES
    "de" -> I18nDe.VALUES
    "es" -> I18nEs.VALUES
    else -> I18nEn.VALUES
}
